import logging
from robot.libraries.BuiltIn import BuiltIn, RobotNotRunningError
from taf.launcher.ue_proxy_mngr_fastmile.launcher import Launcher


class ueproxy_mngr_fastmile_launcher(object):
    ROBOT_LIBRARY_SCOPE = "TEST SUITE"
    ROBOT_LISTENER_API_VERSION = 2

    def __init__(self):
        self.ROBOT_LIBRARY_LISTENER = self
        self.logger = logging.getLogger("ueproxy_mngr_fastmile_launcher")
        self.tl = self._get_robot_tl_variable()
        self.launcher = Launcher(self.tl, self.logger)

    def _get_robot_tl_variable(self):
        """
        Retrieves the 'tl' variable from the robot.

        Returns:
            str: The value of the 'tl' variable.

        Raises:
            EnvironmentError: If the 'tl' variable is not found.
        """
        tl = self._get_robot_variable("tl")
        if not tl:
            raise EnvironmentError(
                "taf.launcher.ue_proxy_mngr_fastmile based on taf.config.testline configuration variable. "
                "Please ensure you are using testline configuration correctly"
            )
        return tl

    @staticmethod
    def _get_robot_variable(variable):
        """
        Get the value of a Robot Framework variable.

        Args:
            variable (str): The name of the variable.

        Returns:
            The value of the variable if it exists, otherwise None.
        """
        try:
            return BuiltIn().get_variable_value("${{{}}}".format(variable))
        except RobotNotRunningError:
            return None

    def start_ueproxy_mngr(self, wait_time=2):
        """
        Starts the UE Proxy Manager.

        Args:
            wait_time (int): The time to wait before checking if UE Proxy Manager started. Default is 2 seconds.
        """
        self.launcher.start_ueproxy_mngr(wait_time=wait_time)

    def stop_ueproxy_mngr(self):
        """
        Stops the UE Proxy Manager.

        Args:
            None

        Returns:
            None
        """
        self.launcher.stop_ueproxy_mngr()
